files.hooks/register.tsx:
// Last Look: holds a destructive shell command (the Bash tool, and the Monitor
// tool's command), measures what it would destroy, and waits for the person
// to press Cancel or Proceed.
//
// A safety net, not a permission system: it judges commands by their text,
// measures with read-only commands, and on any fault of its own it stops the
// command rather than let it run unchecked.

import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, RenderSurface } from 'claude-code'

import type { LastLookHold, LastLookReport } from '../types'
import { classify } from './classify'
import { MEASURE_ENV, measureAll, shouldHold } from './measure'
import type { Ctx, Probe } from './measure'
import { parseAllow } from './paths'
import { clean } from './text'
import { drawHold } from './view'

const PANE = 'last-look'
const holds = atom({ plugin: 'last-look', key: 'holds' } as const, [])

type Choice = 'proceed' | 'cancel'
type Outcome = Choice | 'aborted' | 'no-wait' | 'nowhere'

/**
 * The press handlers' way back to the waiting hook. A function cannot live in
 * $.state, so this one map is module state; a hold it no longer knows (the
 * module reloaded) is simply cleared when pressed.
 */
const waiting = new Map<string, (choice: Choice) => void>()

/**
 * What the hold keeps in flight while it waits. A hook's 10 s budget counts
 * only its own running time and stands still while a `$` call is in flight,
 * but a `$.clock` wait counts; so the hold keeps one cheap, read-only
 * `sleep` running until the person answers. The second line is for Windows.
 */
const SLEEPERS: readonly (readonly string[])[] = [
  ['sleep', '1'],
  ['powershell', '-NoProfile', '-Command', 'Start-Sleep -Seconds 1'],
]

const STATUS = 'holding a command: Cancel or Proceed'
const LOGGED: Record<Outcome, string> = {
  proceed: 'you let this run',
  cancel: 'you cancelled',
  aborted: 'stopped when the turn was interrupted',
  'no-wait': 'stopped, it could not wait for your review',
  nowhere: 'stopped, nowhere to show the review',
}
const STOP = 'Do not retry it or reach the same result another way; ask the person what they want instead.'
const FAILED = 'last-look: its safety check failed, so this command was stopped instead of running unchecked. Ask the person to run it themselves if they intend it.'

export const register: Register = (on, options) => {
  const allow = parseAllow(String(options.alwaysAllow ?? ''))

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    // Judge first: nothing runs until this hook has decided.
    const verdict = await guard($, e.command, e.tool_use_id, e.agentId, next.signal, allow)
    return verdict === 'run' ? next(e) : { deny: verdict.deny }
  }).catch(($, e, next) => (next.called ? next(e) : { deny: FAILED }))

  // The Monitor tool runs a shell command too.
  on('tool.call', { tool: 'Monitor' }, async ($, e, next) => {
    if (e.command === undefined) return next(e)
    const verdict = await guard($, e.command, e.tool_use_id, e.agentId, next.signal, allow)
    return verdict === 'run' ? next(e) : { deny: verdict.deny }
  }).catch(($, e, next) => (next.called ? next(e) : { deny: FAILED }))

  // Closing the pane by hand (its close mark, Esc) is a Cancel.
  on('ui.close', { id: PANE }, async ($, e, next) => {
    if (e.origin.kind === 'person') for (const resolve of waiting.values()) resolve('cancel')
    return next(e)
  }).catch(($, e, next) => next(e))

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const kit = $.ui.resolve(e)
    const list = await read($, holds)
    const first = list[0]
    if (!first) return <kit.Text dimColor>Nothing is held right now.</kit.Text>
    return drawHold(kit, first, {
      rows: e.props.scroll.bodyRows,
      columns: e.props.bodyColumns,
      compact: false,
      surface: e.surface,
      queued: list.length - 1,
      onCancel: () => decide($, first.id, 'cancel'),
      onProceed: () => decide($, first.id, 'proceed'),
    })
  })

  // The band above the prompt: where the pane has no room to open. While a
  // hold waits it draws ALONE: another mod's band holding one control
  // character would make the engine refuse the whole tree, and the hold with
  // its Cancel button would vanish. With nothing held, the band is theirs.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const list = await read($, holds)
    const first = list.find(held => held.mode === 'band')
    if (!first) return next(e)
    return drawHold($.ui.resolve(e), first, {
      rows: e.props.maxRows,
      columns: e.props.bodyColumns,
      compact: true,
      surface: e.surface,
      queued: list.length - 1,
      onCancel: () => decide($, first.id, 'cancel'),
      onProceed: () => decide($, first.id, 'proceed'),
    })
  })
}

/**
 * Classifies, measures and, when it must, holds one shell command until the
 * person decides. `run`: let it run; else the refusal the model reads.
 */
async function guard($: EngineInterface, command: string, id: string, agentId: string | undefined, signal: AbortSignal, allow: readonly string[]): Promise<'run' | { deny: string }> {
  const home = await $.env.get('HOME')
  // Classified once: brace expansion is capped, but never paid for twice.
  const findings = classify(command, home === undefined ? {} : { home })
  if (findings.length === 0) return 'run'
  const ctx = await context($, home, allow)

  $.ui.status(`measuring: ${clip(command, 60)}`)
  let report: LastLookReport
  try {
    report = await measureAll(ctx, command, findings)
  } finally {
    $.ui.status(undefined)
  }
  if (!shouldHold(report)) return 'run'

  const surfaces = await $.session.surfaces()
  if (surfaces.length === 0) {
    return { deny: `last-look: nobody can review this command in this session, so it was stopped (${report.headline}). Ask the person to run it themselves if they intend it.` }
  }
  const outcome = await hold($, { id, report, isSubagent: agentId !== undefined }, surfaces, signal)
  // Claude Code already labels the line with the plugin's name.
  $.ui.log(`${LOGGED[outcome]}: ${clip(command, 80)}`)
  return outcome === 'proceed' ? 'run' : { deny: refusal(outcome, report) }
}

async function context($: EngineInterface, home: string | undefined, allow: readonly string[]): Promise<Ctx> {
  const [cwd, root, now] = await Promise.all([$.session.cwd(), $.session.root(), $.clock.now()])
  // Read-only: a command by argv (no shell), a stat, a directory listing.
  const probe: Probe = {
    run: (argv, cwd, timeoutMs) => $.process.run(argv, { cwd, timeoutMs, env: MEASURE_ENV }),
    // Missing is undefined; a stat that fails for another reason (permissions)
    // rejects, so that part is held unmeasured instead of read as not there.
    stat: async path => {
      try {
        return await $.fs.stat(path, { resolve: true })
      } catch (error) {
        if (await $.fs.exists(path)) throw error
        return undefined
      }
    },
    list: path => $.fs.list(path),
  }
  const real = (path: string) => probe.stat(path).then(s => s?.realPath ?? path, () => path)
  const [cwdReal, rootReal] = await Promise.all([real(cwd), real(root)])
  return { probe, cwd, cwdReal, root, rootReal, allow, now, ...(home === undefined ? {} : { home }) }
}

async function hold($: EngineInterface, entry: Omit<LastLookHold, 'mode'>, surfaces: readonly RenderSurface[], signal: AbortSignal): Promise<Outcome> {
  const decision = new Promise<Choice>(resolve => waiting.set(entry.id, resolve))
  try {
    // State first, so the pane's first drawing already has the report.
    await update($, holds, list => [...list.filter(held => held.id !== entry.id), { ...entry, mode: 'pane' as const }])
    // No `focus`: the pane never takes the keyboard on its own. With it, a
    // person typing their next prompt as the hold appears would be typing into
    // the pane (Tab then Enter could reach Proceed). They click or ctrl+x tab
    // in, and then Cancel holds the focus, so Enter cancels.
    const opened = await $.ui
      .open({ id: PANE, title: 'Last Look', closeOnEscape: true, holdToasts: true, rows: 22, columns: 72 })
      .catch(() => ({ isPlaced: false as const, reason: 'refused' }))
    if (!opened.isPlaced) {
      // A pane opened unasked waits on narrow terminals: use the band.
      if (!surfaces.some(s => s === 'terminal' || s === 'desktop')) return 'nowhere'
      await update($, holds, list => list.map(held => (held.id === entry.id ? { ...held, mode: 'band' as const } : held)))
    }
    $.ui.status(STATUS)
    return await waitFor($, decision, signal)
  } finally {
    waiting.delete(entry.id)
    const left = await update($, holds, list => list.filter(held => held.id !== entry.id)).catch(() => [])
    if (left.length === 0) {
      $.ui.status(undefined)
      await $.ui.close({ id: PANE }).catch(() => undefined)
    }
  }
}

async function waitFor($: EngineInterface, decision: Promise<Choice>, signal: AbortSignal): Promise<Outcome> {
  const aborted = new Promise<'aborted'>(resolve => {
    if (signal.aborted) resolve('aborted')
    else signal.addEventListener('abort', () => resolve('aborted'), { once: true })
  })
  let sleeper = 0
  while (true) {
    const argv = SLEEPERS[sleeper]
    if (!argv) return 'no-wait'
    const tick = $.process.run([...argv], { timeoutMs: 10_000 }).then(
      () => 'tick' as const,
      () => 'broken' as const,
    )
    const first = await Promise.race([decision, aborted, tick])
    if (first === 'broken') sleeper++
    else if (first !== 'tick') return first
  }
}

async function decide($: EngineInterface, id: string, choice: Choice): Promise<void> {
  const resolve = waiting.get(id)
  if (resolve) return resolve(choice)
  // Nothing waits on it (an earlier load of this module): clear it away.
  const left = await update($, holds, list => list.filter(held => held.id !== id))
  if (left.length === 0) await $.ui.close({ id: PANE })
}

function refusal(outcome: Exclude<Outcome, 'proceed'>, report: LastLookReport): string {
  if (outcome === 'cancel') return `last-look: the person reviewed this command and chose Cancel, so it did not run (${report.headline}). ${STOP}`
  if (outcome === 'aborted') return `last-look: this command was held for review when the turn was interrupted, so it did not run. ${STOP}`
  if (outcome === 'nowhere') return 'last-look: this session has no terminal or desktop view to show the review in, so the command was stopped. Ask the person to run it themselves if they intend it.'
  return 'last-look: it could not wait for a review here (no sleep command to wait with), so it stopped the command. Ask the person to run it themselves if they intend it.'
}

/** One clean, short line of untrusted text for the status line and the log. */
function clip(text: string, max: number): string {
  const line = clean(text).replace(/\s+/g, ' ').trim()
  return line.length <= max ? line : `${line.slice(0, max - 3)}...`
}

files.hooks/classify.ts:
// Pure: given a Bash command string, which parts of it can destroy work?
//
// No `$`, no I/O: the hook measures what this finds. The rule of thumb is to
// catch what the spec names in every spelling a model actually writes (flag
// order, sudo and env prefixes, quoted paths, `cd x && ...`, subshells,
// `bash -c`, `$(...)`), and to leave look-alikes alone (`echo "rm -rf"`,
// `grep -r`, a single-file `rm`).

import { literal, parse } from './shell'
import type { Item, Part, RawWord, Redir, Seq } from './shell'

/** A word as the shell would hand it to the program, when that can be known. */
export type Word = {
  text: string
  /** False when it holds an expansion nobody can know ahead (`$X`, `$(...)`). */
  known: boolean
  /** True when unquoted `*`, `?` or `[` make it a pattern the shell expands. */
  glob: boolean
  /** As written in the command. */
  raw: string
  /**
   * A literal path as written: no glob, brace, `$VAR`, `~`, `$(...)` or
   * backticks. Only such paths may be skipped by alwaysAllow, and only they
   * can be reported "not found" with confidence.
   */
  plain: boolean
}

/** One `cd` on the way to where a command runs. */
export type CdStep = {
  dir: Word
  /**
   * True when the command runs even if this `cd` fails (`cd x; rm ...`),
   * so it then runs where the shell already was.
   */
  soft: boolean
}

export type Kind =
  | 'rm'
  | 'find-delete'
  | 'xargs-rm'
  | 'git-clean'
  | 'git-reset-hard'
  | 'git-discard'
  | 'git-push-force'
  | 'git-branch-delete'
  | 'git-worktree-remove'
  | 'redirect'

export type GitInfo =
  /** `forces`: 2 for `-ff`, which also removes nested git repositories. */
  | { sub: 'clean'; flags: string[]; forces: number; excludes: string[]; paths: Word[] }
  | { sub: 'reset'; ref?: Word }
  | {
      sub: 'discard'
      /** `all`: every uncommitted change; `maybe-ref`: `git checkout x`, a branch or a path. */
      mode: 'all' | 'paths' | 'maybe-ref'
      source?: Word
      /** True when the files come back from the index, so staged work survives. */
      fromIndex: boolean
      paths: Word[]
    }
  | { sub: 'push'; remote?: Word; refspecs: Word[]; isWholeRepo: boolean }
  | { sub: 'branch'; names: Word[] }
  | { sub: 'worktree'; paths: Word[] }

export type Finding = {
  kind: Kind
  /** The command's own text, for the person to read. */
  label: string
  /** The `cd`s between the session's directory and where it runs. */
  cd: CdStep[]
  /** What it acts on: rm operands, find start points, the redirect's file. */
  targets: Word[]
  isSudo: boolean
  git?: GitInfo
  /** For find: a read-only argv that lists what it would delete. */
  findListing?: string[]
  /** Why it cannot be measured, when that is plain from the text alone. */
  unknown?: string
  /**
   * The whole command is this one simple command and this redirect is all it
   * does that we see: no `&&`, `||`, `;`, `|`, `&`, newline, subshell,
   * `$(...)` or unquoted here-doc. Only then can "the target does not exist"
   * be judged before anything runs.
   */
  isSole?: boolean
}

export type ClassifyEnv = { home?: string }

/** How deep `$(...)`, `bash -c` and `eval` may nest before we stop looking. */
const MAX_DEPTH = 6

export function classify(command: string, env: ClassifyEnv = {}): Finding[] {
  const out: Finding[] = []
  const seq = parse(command)
  walk(seq, command, [], new Map(), env, out, 0)
  const only = out[0]
  if (out.length === 1 && only?.kind === 'redirect' && isSoleCommand(seq)) only.isSole = true
  return out
}

/** One simple command, nothing before or after it, nothing running inside it. */
function isSoleCommand(seq: Seq): boolean {
  const item = seq[0]
  if (seq.length !== 1 || !item || item.kind !== 'simple' || (item.op !== '' && item.op !== ';')) return false
  const words = [...item.words, ...item.redirs.flatMap(r => (r.target ? [r.target] : []))]
  if (words.some(w => w.parts.some(p => p.t === 'sub'))) return false
  if (item.redirs.some(r => (r.op === '<<' || r.op === '<<-') && !r.isQuotedDoc)) return false
  return item.redirs.filter(r => r.op === '>' || r.op === '>|' || r.op === '&>' || r.op === '>&').length === 1
}

type Vars = Map<string, string | undefined>

function walk(seq: Seq, src: string, cd: CdStep[], vars: Vars, env: ClassifyEnv, out: Finding[], depth: number): CdStep[] {
  let steps = cd
  seq.forEach((item, index) => {
    const before = seq[index - 1]?.op ?? ''
    // A pipeline part and a `&` command run in a subshell: their `cd` stays there.
    const isPiped = item.op === '|' || item.op === '|&' || item.op === '&' || before === '|' || before === '|&'
    if (item.kind === 'group') {
      const after = walk(item.body, src, steps, vars, env, out, depth)
      redirects(item.redirs, item, src, steps, vars, env, out, depth)
      if (!item.subshell && !isPiped) steps = after
      return
    }
    const next = simple(item, src, steps, vars, env, out, depth)
    if (!isPiped) steps = next
  })
  return steps
}

const RESERVED = new Set(['if', 'then', 'else', 'elif', 'fi', 'do', 'done', 'while', 'until', 'esac', '!', 'time', '{', '}'])
const HEADERS = new Set(['for', 'select', 'case', 'function'])
const SHELLS = new Set(['bash', 'sh', 'zsh', 'dash', 'ksh'])

/** Classifies one simple command; returns the `cd` steps after it. */
function simple(item: Item & { kind: 'simple' }, src: string, cd: CdStep[], vars: Vars, env: ClassifyEnv, out: Finding[], depth: number): CdStep[] {
  const label = src.slice(item.start, item.end).trim()
  const words = item.words.flatMap(w => resolveAll(w, src, vars, env))
  // Commands inside the words run first, wherever the shell is now.
  for (const w of item.words) subs(w, cd, vars, env, out, depth)
  // Inside `[[ ... ]]` a `>` compares two strings; it writes no file.
  const isTest = words[0]?.known === true && words[0].text === '[['
  if (!isTest) redirects(item.redirs, item, src, cd, vars, env, out, depth)

  let argv = words
  while (argv[0] && RESERVED.has(argv[0].text) && argv[0].known) argv = argv.slice(1)
  // `function f { body }`: the body is a command like any other.
  if (argv[0]?.known && argv[0].text === 'function') {
    argv = argv.slice(2)
    while (argv[0]?.known && (argv[0].text === '{' || argv[0].text === '()')) argv = argv.slice(1)
  }
  const head = argv[0]
  if (!head || !head.known) return cd
  if (HEADERS.has(head.text)) return cd

  // Assignments alone set shell variables; before a command they are its env.
  const firstCommand = argv.findIndex(w => !isAssignment(w))
  if (firstCommand === -1 || ['export', 'local', 'declare', 'readonly', 'typeset'].includes(head.text)) {
    for (const w of argv) {
      if (!isAssignment(w)) continue
      const name = w.raw.slice(0, w.raw.indexOf('='))
      vars.set(name, w.known ? w.text.slice(w.text.indexOf('=') + 1) : undefined)
    }
    return cd
  }
  argv = argv.slice(firstCommand)

  const peeled = peel(argv)
  argv = peeled.argv
  const program = argv[0]
  if (!program || !program.known) return cd
  const name = base(program.text)
  const steps = [...cd, ...peeled.cd]
  const finding = (kind: Kind, rest: Partial<Finding>): void => {
    out.push({ kind, label, cd: steps, targets: [], isSudo: peeled.isSudo, ...rest })
  }

  if (name === 'cd' || name === 'pushd') {
    const operand = argv.slice(1).find(w => !(w.known && /^(-[LPe@]+|--)$/.test(w.text)))
    const dir = operand ?? { text: env.home ?? '', known: env.home !== undefined, glob: false, raw: '~', plain: false }
    if (dir.known && dir.text === '-') return [...cd, { dir: { ...dir, known: false }, soft: false }]
    return [...cd, { dir, soft: item.op !== '&&' }]
  }
  if (name === 'popd') return [...cd, { dir: { text: '', known: false, glob: false, raw: 'popd', plain: false }, soft: false }]

  if (peeled.viaXargs && name === 'rm') {
    finding('xargs-rm', { unknown: 'it deletes whatever the command before it prints' })
    return cd
  }
  if (SHELLS.has(name) && depth < MAX_DEPTH) {
    const script = shellScript(argv)
    if (script?.known) walk(parse(script.text), script.text, steps, new Map(vars), env, out, depth + 1)
    return cd
  }
  if (name === 'eval' && depth < MAX_DEPTH) {
    const text = argv.slice(1).map(w => w.text).join(' ')
    if (argv.slice(1).every(w => w.known)) walk(parse(text), text, steps, new Map(vars), env, out, depth + 1)
    return cd
  }
  if (name === 'rm') {
    const rm = parseRm(argv)
    if (rm.isRecursive && rm.operands.length > 0) finding('rm', { targets: rm.operands })
  } else if (name === 'find') {
    const found = parseFind(argv)
    if (found) finding('find-delete', found)
  } else if (name === 'git') {
    const git = parseGit(argv, peeled.viaXargs)
    if (git) {
      const unknown = peeled.viaXargs ? 'more arguments come from the command before it' : git.finding.unknown
      out.push({ label, cd: [...steps, ...git.cd], targets: [], isSudo: peeled.isSudo, ...git.finding, ...(unknown ? { unknown } : {}) })
    }
  }
  return cd
}

function redirects(redirs: Redir[], item: Item, src: string, cd: CdStep[], vars: Vars, env: ClassifyEnv, out: Finding[], depth: number): void {
  for (const r of redirs) {
    if (!r.target || r.target.parts.length === 0) continue
    subs(r.target, cd, vars, env, out, depth)
    const overwrites = r.op === '>' || r.op === '>|' || r.op === '&>' || r.op === '>&'
    if (!overwrites) continue
    const target = resolve(r.target, src, vars, env)
    if (target.known && (target.text.startsWith('/dev/') || target.text === '')) continue
    out.push({
      kind: 'redirect',
      label: src.slice(item.start, item.end).trim(),
      cd,
      targets: [target],
      isSudo: false,
      ...(target.known ? {} : { unknown: `it writes to ${target.raw}, which is only known when it runs` }),
    })
  }
}

/** Walks the commands a word runs inside it (`$(...)`, backticks). */
function subs(w: RawWord, cd: CdStep[], vars: Vars, env: ClassifyEnv, out: Finding[], depth: number): void {
  if (depth >= MAX_DEPTH) return
  for (const p of w.parts) {
    if (p.t === 'sub') walk(parse(p.src), p.src, cd, new Map(vars), env, out, depth + 1)
  }
}

// ---------------------------------------------------------------- words

function resolve(w: RawWord, src: string, vars: Vars, env: ClassifyEnv): Word {
  let text = ''
  let known = true
  let glob = false
  let plain = true
  w.parts.forEach((p: Part, index) => {
    if (p.t === 'lit') {
      let s = p.s
      if (index === 0 && !p.quoted && s.startsWith('~')) {
        plain = false
        const user = /^~([^/]*)/.exec(s)?.[1] ?? ''
        if (user === '' && env.home !== undefined) s = env.home + s.slice(1)
        else known = false
      }
      if (!p.quoted && /[*?[]/.test(s)) glob = true
      // An unquoted brace may expand (or be refused) by the shell: not a plain path.
      if (!p.quoted && /[{}]/.test(s)) plain = false
      text += s
    } else if (p.t === 'var') {
      plain = false
      const value = vars.has(p.name) ? vars.get(p.name) : p.name === 'HOME' ? env.home : undefined
      // Unquoted, bash splits the value on spaces and globs it: one word no more.
      if (value === undefined || (!p.quoted && /[\s*?[]/.test(value))) known = false
      else text += value
    } else {
      plain = false
      known = false
    }
  })
  return { text, known, glob, raw: src.slice(w.start, w.end), plain: plain && !glob }
}

export function literalWord(text: string): Word {
  return { text, known: true, glob: false, raw: text, plain: true }
}

/** Resolves a word, expanding braces (`{a,b}`, `{1..3}`) the way the shell would first. */
function resolveAll(w: RawWord, src: string, vars: Vars, env: ClassifyEnv): Word[] {
  const only = w.parts.length === 1 ? w.parts[0] : undefined
  // Bash does not brace-expand an assignment (`X={a,b}`), so neither do we.
  const isBraced = only?.t === 'lit' && !only.quoted && /\{[^{}]*(,|\.\.)[^{}]*\}/.test(only.s) && !/^[A-Za-z_][A-Za-z0-9_]*=/.test(only.s)
  if (!isBraced || only?.t !== 'lit') return [resolve(w, src, vars, env)]
  const expanded = braces(only.s)
  const raw = src.slice(w.start, w.end)
  // Past the cap the word is unknown, so it is held, never cut short.
  if (!expanded) return [{ text: only.s, known: false, glob: false, raw, plain: false }]
  return expanded.map(s => ({ ...resolve({ ...w, parts: [{ t: 'lit', s, quoted: false }] }, src, vars, env), plain: false }))
}

/** Most words one brace expression may become, and most nested groups, before it counts as unknown. */
const BRACE_CAP = 256
const BRACE_GROUPS = 8

/**
 * Brace expansion with bounded work: comma lists and `{1..9}` / `{a..e}`
 * ranges, generated one at a time; undefined once past the cap.
 */
export function braces(s: string): string[] | undefined {
  const out: string[] = []
  const expand = (text: string, depth: number): boolean => {
    if (depth > BRACE_GROUPS) return false
    const group = braceGroup(text)
    if (!group) {
      out.push(text)
      return out.length <= BRACE_CAP
    }
    if (group.alternatives === undefined) return false
    for (const alternative of group.alternatives) {
      if (!expand(group.head + alternative + group.tail, depth + 1)) return false
    }
    return true
  }
  return expand(s, 0) ? out : undefined
}

/** The first `{...}` that expands: its alternatives (undefined: too many), and what is around it. */
function braceGroup(s: string): { head: string; tail: string; alternatives: string[] | undefined } | undefined {
  for (let open = s.indexOf('{'); open !== -1; open = s.indexOf('{', open + 1)) {
    let depth = 0
    const commas: number[] = []
    for (let j = open; j < s.length; j++) {
      if (s[j] === '{') depth++
      else if (s[j] === '}') depth--
      else if (s[j] === ',' && depth === 1) commas.push(j)
      if (depth !== 0) continue
      const head = s.slice(0, open)
      const tail = s.slice(j + 1)
      const body = s.slice(open + 1, j)
      if (commas.length > 0) {
        const cuts = [open, ...commas, j]
        return { head, tail, alternatives: cuts.slice(1).map((cut, k) => s.slice((cuts[k] ?? open) + 1, cut)) }
      }
      const range = /^(-?\d+|[a-zA-Z])\.\.(-?\d+|[a-zA-Z])$/.exec(body)
      if (range) return { head, tail, alternatives: sequence(range[1] ?? '', range[2] ?? '') }
      break
    }
  }
  return undefined
}

function sequence(from: string, to: string): string[] | undefined {
  const isNumber = /\d/.test(from)
  if (isNumber !== /\d/.test(to)) return undefined
  const a = isNumber ? Number(from) : from.charCodeAt(0)
  const b = isNumber ? Number(to) : to.charCodeAt(0)
  if (Math.abs(b - a) >= BRACE_CAP) return undefined
  const step = a <= b ? 1 : -1
  const out: string[] = []
  for (let n = a; step > 0 ? n <= b : n >= b; n += step) out.push(isNumber ? String(n) : String.fromCharCode(n))
  return out
}

function isAssignment(w: Word): boolean {
  return /^[A-Za-z_][A-Za-z0-9_]*=/.test(w.raw)
}

export function base(path: string): string {
  return path.slice(path.lastIndexOf('/') + 1)
}

// ---------------------------------------------------------------- prefixes

type Peeled = { argv: Word[]; cd: CdStep[]; isSudo: boolean; viaXargs: boolean }

/** Options of each prefix command that take a value of their own. */
const VALUED: Record<string, readonly string[]> = {
  sudo: ['-u', '-g', '-C', '-D', '-h', '-p', '-r', '-t', '-T', '-U', '--user', '--group', '--chdir'],
  doas: ['-u', '-C'],
  env: ['-u', '-C', '-S', '-P', '--unset', '--chdir', '--split-string'],
  nice: ['-n', '--adjustment'],
  ionice: ['-c', '-n', '-p', '-P', '-u', '--class', '--classdata'],
  stdbuf: ['-i', '-o', '-e', '--input', '--output', '--error'],
  timeout: ['-s', '-k', '--signal', '--kill-after'],
  exec: ['-a'],
  xargs: ['-E', '-I', '-L', '-n', '-P', '-s', '-d', '-a', '--arg-file', '--delimiter', '--max-args', '--max-procs', '--max-chars', '--max-lines', '--replace', '--eof'],
}
const PREFIXES = new Set([...Object.keys(VALUED), 'nohup', 'time', 'command', 'builtin', 'chronic', 'caffeinate', 'unbuffer'])

/** Strips `sudo`, `env X=1`, `nohup`, `xargs` and kin down to the real program. */
function peel(words: Word[]): Peeled {
  let argv = words
  const cd: CdStep[] = []
  let isSudo = false
  let viaXargs = false
  for (let guard = 0; guard < 8; guard++) {
    const head = argv[0]
    if (!head?.known) break
    const name = base(head.text)
    if (!PREFIXES.has(name)) break
    if (name === 'command' && argv.slice(1).some(w => w.text === '-v' || w.text === '-V')) return { argv: [], cd, isSudo, viaXargs }
    if (name === 'sudo' || name === 'doas') isSudo = true
    if (name === 'xargs') viaXargs = true
    const valued = VALUED[name] ?? []
    let k = 1
    while (k < argv.length) {
      const w = argv[k]
      if (!w?.known) break
      if (w.text === '--') {
        k++
        break
      }
      if (name === 'env' && isAssignment(w)) {
        k++
        continue
      }
      if (!w.text.startsWith('-') || w.text === '-') break
      const flag = w.text.split('=')[0] ?? ''
      const takesValue = valued.includes(flag) && !w.text.includes('=')
      const value = takesValue ? argv[k + 1] : w.text.includes('=') ? { ...w, text: w.text.slice(w.text.indexOf('=') + 1) } : undefined
      if ((name === 'env' && (flag === '-C' || flag === '--chdir')) || (name === 'sudo' && (flag === '-D' || flag === '--chdir'))) {
        if (value) cd.push({ dir: value, soft: false })
      }
      k += takesValue ? 2 : 1
    }
    // `timeout 10 cmd`: the duration comes before the command.
    if (name === 'timeout' && argv[k]?.known && /^[\d.]+[smhd]?$/.test(argv[k]?.text ?? '')) k++
    argv = argv.slice(k)
    // `sudo FOO=1 rm ...`: variables set for the command, not the command.
    while (argv[0] && isAssignment(argv[0])) argv = argv.slice(1)
  }
  return { argv, cd, isSudo, viaXargs }
}

/** `bash -c 'script'`: the script, or undefined when there is no `-c`. */
function shellScript(argv: Word[]): Word | undefined {
  let hasC = false
  for (let k = 1; k < argv.length; k++) {
    const w = argv[k]
    if (!w) break
    if (w.known && /^-[a-zA-Z]+$/.test(w.text)) {
      if (w.text.includes('c')) hasC = true
      if (w.text === '-o' || w.text === '-O') k++
      continue
    }
    if (w.known && w.text.startsWith('--')) continue
    return hasC ? w : undefined
  }
  return undefined
}

// ---------------------------------------------------------------- rm

export function parseRm(argv: Word[]): { isRecursive: boolean; operands: Word[] } {
  let isRecursive = false
  let isEnd = false
  const operands: Word[] = []
  for (const w of argv.slice(1)) {
    const t = w.text
    if (!isEnd && w.known && t === '--') isEnd = true
    else if (!isEnd && w.known && t.startsWith('--')) {
      // GNU takes any unique prefix of a long option: --rec, --recur.
      if (t.length >= 3 && '--recursive'.startsWith(t)) isRecursive = true
    } else if (!isEnd && w.known && t.startsWith('-') && t.length > 1) {
      if (/[rR]/.test(t)) isRecursive = true
    } else operands.push(w)
  }
  return { isRecursive, operands }
}

// ---------------------------------------------------------------- find

const FIND_LEADING = new Set(['-H', '-L', '-P', '-E', '-X', '-s', '-x', '-d'])
const FIND_VALUED = new Set([
  '-name', '-iname', '-path', '-ipath', '-wholename', '-iwholename', '-regex', '-iregex', '-lname', '-ilname',
  '-type', '-xtype', '-size', '-perm', '-user', '-group', '-uid', '-gid', '-maxdepth', '-mindepth', '-mtime',
  '-atime', '-ctime', '-mmin', '-amin', '-cmin', '-newer', '-anewer', '-cnewer', '-samefile', '-inum', '-links',
  '-fstype', '-used', '-context', '-printf', '-fprint', '-fprint0', '-fls', '-regextype', '-newermt', '-newerct',
  '-newerat', '-newerBt',
])
const FIND_EXEC = new Set(['-exec', '-execdir', '-ok', '-okdir'])
/**
 * Predicates that write files or run commands. Never copied into a measuring
 * command: a find holding one is held unmeasured (GNU find opens -fprint
 * files for writing while it parses, before it runs anything).
 */
export const FIND_WRITES = new Set(['-delete', '-exec', '-execdir', '-ok', '-okdir', '-fprint', '-fprint0', '-fprintf', '-fls'])
/** Tests whose meaning differs between the system find and the shell's own (bfs, GNU). */
const FIND_UNPORTABLE = new Set(['-regex', '-iregex', '-regextype', '-readable', '-writable', '-executable'])
/** Actions that write or print on their own: a listing re-run would not be clean. */
const FIND_SIDE_EFFECTS = new Set(['-exec', '-execdir', '-ok', '-okdir', '-fprint', '-fprint0', '-fprintf', '-fls', '-delete', '-print', '-print0', '-printf', '-ls'])

export function parseFind(argv: Word[]): Partial<Finding> | undefined {
  const args = argv.slice(1)
  let k = 0
  const leading: string[] = []
  while (k < args.length) {
    const t = args[k]?.text ?? ''
    if (FIND_LEADING.has(t) || /^-O\d$/.test(t)) {
      leading.push(t)
      k++
    } else if (t === '-D' || t === '-f') {
      leading.push(t, args[k + 1]?.text ?? '')
      k += 2
    } else break
  }
  const starts: Word[] = []
  while (k < args.length) {
    const t = args[k]?.text ?? ''
    if (args[k]?.known && (t.startsWith('-') || t === '(' || t === '!' || t === ')' || t === ',')) break
    const w = args[k]
    if (w) starts.push(w)
    k++
  }
  const expr = args.slice(k)

  // Scan the expression, skipping the values of tests that take one.
  let deletes = false
  let usesDelete = false
  const listing: string[] = []
  const isKnown = expr.every(w => w.known) && starts.every(w => w.known && !w.glob)
  let isListable = true
  let isPortable = true
  for (let j = 0; j < expr.length; j++) {
    const t = expr[j]?.text ?? ''
    // Writers first: -fprint takes a value, but must never reach the listing.
    if (t === '-fprint' || t === '-fprint0' || t === '-fprintf' || t === '-fls') {
      isListable = false
      j += t === '-fprintf' ? 2 : 1
      continue
    }
    if (FIND_UNPORTABLE.has(t)) isPortable = false
    if (FIND_VALUED.has(t)) {
      listing.push(t, expr[j + 1]?.text ?? '')
      j++
      continue
    }
    if (t === '-delete') {
      deletes = true
      usesDelete = true
      listing.push('-print0')
      continue
    }
    if (FIND_EXEC.has(t)) {
      let end = j + 1
      while (end < expr.length && expr[end]?.text !== ';' && expr[end]?.text !== '+') end++
      // `-exec sudo rm`, `-exec env rm`: peel the same prefixes as a command line.
      const command = peel(expr.slice(j + 1, end)).argv
      const program = command[0]?.known ? base(command[0].text) : ''
      if (program === 'rm') {
        deletes = true
        listing.push('-print0')
      } else if (SHELLS.has(program) || program === 'eval' || program === 'xargs' || !command[0]?.known) {
        // A shell or a run-time program could delete anything: held unmeasured.
        deletes = true
        isListable = false
      } else {
        isListable = false
      }
      j = end
      continue
    }
    if (FIND_SIDE_EFFECTS.has(t)) isListable = false
    listing.push(t)
  }
  if (!deletes) return undefined
  const from = starts.length > 0 ? starts : [{ text: '.', known: true, glob: false, raw: '.', plain: true }]
  if (!isKnown) return { targets: from, unknown: 'it names paths that are only known when it runs' }
  if (!isListable) return { targets: from, unknown: 'its find expression does more than delete, so it was not re-run to look' }
  if (!isPortable) return { targets: from, unknown: 'it uses a find test the system find reads differently from the shell' }
  // -delete turns on -depth, which also switches -prune off: list the same way.
  return { targets: from, findListing: [...leading, ...from.map(w => w.text), ...(usesDelete ? ['-depth'] : []), ...listing] }
}

// ---------------------------------------------------------------- git

/** Options of a branch switch that cannot discard anything. */
const SWITCH_FLAGS = new Set(['-q', '--quiet', '-t', '--track', '--no-track', '--detach', '--progress', '--no-progress', '--guess', '--no-guess'])

type GitParsed = { cd: CdStep[]; finding: Pick<Finding, 'kind' | 'git' | 'unknown'> }

function shortFlags(t: string): string {
  return /^-[A-Za-z]+$/.test(t) ? t.slice(1) : ''
}

export function parseGit(argv: Word[], viaXargs = false): GitParsed | undefined {
  const cd: CdStep[] = []
  let k = 1
  let unknown: string | undefined
  while (k < argv.length) {
    const w = argv[k]
    if (!w?.known || !w.text.startsWith('-')) break
    if (w.text === '-C') {
      const dir = argv[k + 1]
      if (dir) cd.push({ dir, soft: false })
      k += 2
    } else if (w.text === '-c' || w.text === '--git-dir' || w.text === '--work-tree' || w.text === '--namespace') {
      if (w.text !== '-c') unknown = 'it points git at another repository'
      k += 2
    } else {
      if (w.text.startsWith('--git-dir=') || w.text.startsWith('--work-tree=')) unknown = 'it points git at another repository'
      k++
    }
  }
  const sub = argv[k]
  if (!sub?.known) return undefined
  const rest = argv.slice(k + 1)
  const parsed = gitSub(sub.text, rest, viaXargs)
  if (!parsed) return undefined
  return { cd, finding: unknown ? { ...parsed, unknown } : parsed }
}

function gitSub(sub: string, rest: Word[], viaXargs: boolean): Pick<Finding, 'kind' | 'git'> | undefined {
  const positionals: Word[] = []
  const after: Word[] = []
  let isEnd = false
  const flags: string[] = []
  for (let j = 0; j < rest.length; j++) {
    const w = rest[j]
    if (!w) continue
    if (isEnd) after.push(w)
    else if (w.known && w.text === '--') isEnd = true
    else if (w.known && w.text.startsWith('-') && w.text !== '-') {
      flags.push(w.text)
      // Options whose value is a separate word.
      const valued: Record<string, readonly string[]> = {
        clean: ['-e', '--exclude'],
        checkout: ['-b', '-B', '-c', '-C', '--orphan', '--conflict'],
        restore: ['-s', '--source'],
        push: ['-o', '--push-option', '--repo', '--receive-pack', '--exec'],
        branch: ['-u', '--set-upstream-to', '--contains', '--no-contains', '--merged', '--no-merged', '--points-at', '--format', '--sort'],
      }
      if ((valued[sub] ?? []).includes(w.text)) {
        const value = rest[j + 1]
        if (value) flags.push(value.text)
        j++
      }
    } else positionals.push(w)
  }
  const has = (...names: string[]) => flags.some(f => names.includes(f))
  const hasShort = (ch: string) => flags.some(f => shortFlags(f).includes(ch))

  if (sub === 'clean') {
    const forces = flags.reduce((n, f) => n + (f === '--force' ? 1 : (shortFlags(f).match(/f/g) ?? []).length), 0)
    if (forces === 0 || hasShort('n') || has('--dry-run')) return undefined
    const keep = ['d', 'x', 'X'].filter(hasShort)
    const excludes: string[] = []
    flags.forEach((f, j) => {
      if (f === '-e' || f === '--exclude') excludes.push(flags[j + 1] ?? '')
      else if (f.startsWith('--exclude=')) excludes.push(f.slice('--exclude='.length))
    })
    return { kind: 'git-clean', git: { sub: 'clean', flags: keep, forces, excludes, paths: [...positionals, ...after] } }
  }
  if (sub === 'worktree') {
    // `git worktree remove --force` deletes the worktree folder, uncommitted work and all.
    const [action, ...targets] = [...positionals, ...after]
    if (action?.text !== 'remove' || !(has('--force') || hasShort('f'))) return undefined
    return { kind: 'git-worktree-remove', git: { sub: 'worktree', paths: targets } }
  }
  if (sub === 'reset') {
    if (!has('--hard')) return undefined
    const ref = positionals[0]
    return { kind: 'git-reset-hard', git: ref ? { sub: 'reset', ref } : { sub: 'reset' } }
  }
  if (sub === 'checkout') {
    const isForced = has('-f', '--force')
    if (has('-p', '--patch')) return undefined
    if (!isForced && has('-b', '-B', '-c', '-C', '--orphan')) return undefined
    const discard = (mode: 'all' | 'paths' | 'maybe-ref', paths: Word[], source?: Word): Pick<Finding, 'kind' | 'git'> => ({
      kind: 'git-discard',
      git: { sub: 'discard', mode, paths, fromIndex: source === undefined, ...(source ? { source } : {}) },
    })
    if (isEnd) {
      if (after.length > 0) return discard('paths', after, positionals[0])
      return isForced ? discard('all', []) : undefined
    }
    if (isForced) return discard('all', [])
    const [first, ...others] = positionals
    if (!first || (first.known && first.text === '-')) return undefined
    if (others.length > 0) return discard('paths', others, first)
    // Only a bare `git checkout <plain name>` may turn out to be a branch switch
    // (the measurer asks git). Any other option, or a name that is not a plain
    // token, is taken as paths and held.
    const isBare = flags.every(f => SWITCH_FLAGS.has(f.split('=')[0] ?? ''))
    const isPath = !isBare || !first.plain || first.text === '.' || first.text.startsWith('./') || first.text.startsWith(':/')
    return discard(isPath ? 'paths' : 'maybe-ref', [first])
  }
  if (sub === 'restore') {
    const staged = hasShort('S') || has('--staged')
    const worktree = hasShort('W') || has('--worktree')
    if ((staged && !worktree) || hasShort('p') || has('--patch')) return undefined
    const paths = [...positionals, ...after]
    if (paths.length === 0) return undefined
    const sourceAt = flags.findIndex(f => f === '-s' || f === '--source')
    const sourceText = sourceAt >= 0 ? flags[sourceAt + 1] : flags.find(f => f.startsWith('--source='))?.slice('--source='.length)
    const source = sourceText !== undefined ? literalWord(sourceText) : staged ? literalWord('HEAD') : undefined
    return { kind: 'git-discard', git: { sub: 'discard', mode: 'paths', paths, fromIndex: source === undefined, ...(source ? { source } : {}) } }
  }
  if (sub === 'switch') {
    if (!has('--discard-changes', '-f', '--force')) return undefined
    return { kind: 'git-discard', git: { sub: 'discard', mode: 'all', paths: [], fromIndex: false } }
  }
  if (sub === 'push') {
    const name = (f: string) => f.split('=')[0] ?? ''
    // git takes a unique prefix of a long option: --force-with is the lease.
    const isMirror = flags.some(f => name(f) === '--mirror')
    const isForced = has('--force') || hasShort('f') || isMirror || [...positionals, ...after].slice(1).some(w => w.text.startsWith('+'))
    // A lease guards only a push that is not also forced: `--force` (or -f,
    // a `+refspec`, --mirror) switches the lease off, so it is held.
    if (!isForced || has('--dry-run') || hasShort('n')) return undefined
    const isWholeRepo = isMirror || has('--all', '--branches', '--tags')
    const [remote, ...refspecs] = [...positionals, ...after]
    return { kind: 'git-push-force', git: { sub: 'push', refspecs, isWholeRepo, ...(remote ? { remote } : {}) } }
  }
  if (sub === 'branch') {
    const isDelete = hasShort('d') || hasShort('D') || has('--delete')
    const isForced = hasShort('D') || hasShort('f') || has('--force')
    if (!isDelete || !isForced || hasShort('r') || has('--remotes')) return undefined
    // Names after `--` are names too: `git branch -D -- feature`.
    const names = [...positionals, ...after]
    return names.length > 0 || viaXargs ? { kind: 'git-branch-delete', git: { sub: 'branch', names } } : undefined
  }
  return undefined
}

export { literal }

files.hooks/measure.ts:
// Measures what a held command would destroy, to show the person. It never
// decides WHETHER to hold: once the classifier calls a command destructive it
// is held, and an empty or failed measurement only means the hold says
// "could not measure: review it yourself". The two exceptions, both
// classification the text alone cannot finish, are marked `isHarmless`: a
// redirect to a plain path that does not exist yet, and `git checkout <name>`
// that git confirms is a branch. alwaysAllow (plain literal paths only) is
// the one skip the person configures.
//
// Read-only commands only: `find` without -delete (no write or exec predicate
// is ever copied), `du`, and git's rev-parse, for-each-ref, status, ls-files,
// diff-index, diff-files, rev-list, log and clean -n (a dry run), all with optional locks
// off, so git writes nothing either.

import type { FsEntry, FsStat, ProcessRunResult } from 'claude-code'

import type { LastLookItem, LastLookReport, LastLookRow, LastLookTone } from '../types'
import { FIND_WRITES } from './classify'
import type { CdStep, Finding, Word } from './classify'
import { globSegment, hasGlob, isAbsolute, isAllowed, join, rebase, show, within } from './paths'

/**
 * The three read-only things measuring needs from the host. The hooks module
 * builds it from `$` (which never crosses an import); tests can fake it.
 */
export type Probe = {
  run: (argv: readonly string[], cwd: string, timeoutMs: number) => Promise<ProcessRunResult>
  /** A path's stat with `realPath`; undefined when it does not exist, a rejection for any other failure. */
  stat: (path: string) => Promise<FsStat | undefined>
  list: (path: string) => Promise<FsEntry[]>
}

export type Ctx = {
  probe: Probe
  /** The session's working directory, and where its links lead. */
  cwd: string
  cwdReal: string
  /** The project root: alwaysAllow folders are looked for beneath it. */
  root: string
  rootReal: string
  home?: string
  allow: readonly string[]
  now: number
}

export const COULD_NOT = 'could not measure: review it yourself'

/** Findings measured per command; any past it are held unmeasured. */
const MAX_ITEMS = 8
/** Detail rows kept per item: more than any pane shows. */
const MAX_ROWS = 40
/** Paths handed to one du call, and kept from a listing. */
const MAX_ARGS = 2000
const LIST_MS = 8_000
const GIT_MS = 6_000

const GIT = ['git', '-c', 'core.quotePath=false', '-c', 'core.fsmonitor=false']

/** Set on every measuring command: plain English output, no git locks, no prompts. */
export const MEASURE_ENV = { LC_ALL: 'C', GIT_OPTIONAL_LOCKS: '0', GIT_TERMINAL_PROMPT: '0' }

export async function measureAll(ctx: Ctx, command: string, findings: readonly Finding[]): Promise<LastLookReport> {
  const items: LastLookItem[] = []
  for (const finding of findings.slice(0, MAX_ITEMS)) {
    try {
      items.push(await measureOne(ctx, finding))
    } catch (error) {
      items.push(unmeasured(finding, undefined, `measuring failed: ${short(error)}`))
    }
  }
  const extra = findings.length - MAX_ITEMS
  if (extra > 0) {
    items.push({ ...blank(`${extra} more destructive ${extra === 1 ? 'step' : 'steps'}`), effect: 'unknown', summary: COULD_NOT, summaryTone: 'warning' })
  }
  return { command: clip(command, 2000), items, ...headline(items) }
}

/**
 * Every destructive command holds. Only alwaysAllow, or a part that turned out
 * not to be destructive at all (`isHarmless`), lets it through; what the
 * measurement found or failed to find never does.
 */
export function shouldHold(report: LastLookReport): boolean {
  return report.items.some(item => !item.isAllowed && !item.isHarmless)
}

async function measureOne(ctx: Ctx, f: Finding): Promise<LastLookItem> {
  const at = await whereItRuns(ctx, f.cd)
  if ('unknown' in at) return unmeasured(f, undefined, at.unknown)
  const where = show(at.dir, ctx.cwd, ctx.home)
  const notes: LastLookRow[] = at.notes.map(text => ({ text, tone: 'warning' }))
  if (f.isSudo) notes.push({ text: 'It runs with sudo, as root.', tone: 'warning' })
  if (f.unknown) return unmeasured(f, where, f.unknown, notes)
  const git = f.git
  switch (f.kind) {
    case 'rm': {
      const paths = await expand(ctx, at.dir, f.targets)
      return typeof paths === 'string' ? unmeasured(f, where, paths, notes) : remove(ctx, f, where, notes, at.dir, paths, 'words')
    }
    case 'find-delete':
      return findDelete(ctx, f, where, notes, at.dir)
    case 'redirect':
      return overwrite(ctx, f, where, notes, at.dir)
    case 'git-clean':
      return git?.sub === 'clean' ? clean(ctx, f, where, notes, at.dir, git) : unmeasured(f, where, 'unexpected git form', notes)
    case 'git-reset-hard':
    case 'git-discard':
      return discard(ctx, f, where, notes, at.dir)
    case 'git-push-force':
      return push(ctx, f, where, notes, at.dir)
    case 'git-branch-delete':
      return branchDelete(ctx, f, where, notes, at.dir)
    case 'git-worktree-remove': {
      const paths = git?.sub === 'worktree' ? git.paths.map(w => w.raw).join(' ') : ''
      return unmeasured(f, where, `it deletes the worktree ${paths} and any uncommitted work in it`, notes)
    }
    case 'xargs-rm':
      return unmeasured(f, where, 'it deletes whatever the command before it prints', notes)
  }
}

// ---------------------------------------------------------------- where, what

async function whereItRuns(ctx: Ctx, steps: readonly CdStep[]): Promise<{ dir: string; notes: string[] } | { unknown: string }> {
  let dir = ctx.cwd
  const notes: string[] = []
  for (const step of steps) {
    if (!step.dir.known) return { unknown: `it runs after cd ${step.dir.raw}, which is only known when it runs` }
    const next = join(dir, step.dir.text)
    if (step.soft && (await stat(ctx, next))?.kind !== 'dir') {
      notes.push(`cd ${step.dir.raw} would fail, so this would run in ${show(dir, ctx.cwd, ctx.home)}`)
      continue
    }
    dir = next
  }
  return { dir, notes }
}

/** A literal path as written, with no `..` (the kernel resolves `..` after links, not by spelling). */
function isPlainPath(w: Word): boolean {
  return w.plain && !w.text.split('/').includes('..')
}

function plainSteps(steps: readonly CdStep[]): boolean {
  return steps.every(step => isPlainPath(step.dir))
}

type Path = { abs: string; slash: boolean; plain: boolean }

/** Words to absolute paths, expanding globs as the shell would where it can. */
async function expand(ctx: Ctx, dir: string, words: readonly Word[]): Promise<Path[] | string> {
  const out: Path[] = []
  for (const w of words) {
    if (!w.known) return `it acts on ${w.raw}, which is only known when it runs`
    const slash = w.text.endsWith('/')
    if (!w.glob) {
      out.push({ abs: join(dir, w.text), slash, plain: isPlainPath(w) })
      continue
    }
    // zsh and bash differ on `**`; no single answer to measure against.
    if (w.text.includes('**')) return `it uses a recursive ** pattern (${w.raw}), which shells expand differently`
    const matches = await glob(ctx, dir, w.text)
    out.push(...(matches.length > 0 ? matches.map(abs => ({ abs, slash, plain: false })) : [{ abs: join(dir, w.text), slash, plain: false }]))
  }
  return out
}

async function glob(ctx: Ctx, dir: string, pattern: string): Promise<string[]> {
  let current = [isAbsolute(pattern) ? '/' : dir]
  for (const segment of pattern.split('/')) {
    if (segment === '' || segment === '.') continue
    if (!hasGlob(segment)) {
      current = current.map(path => join(path, segment))
      continue
    }
    const wanted = globSegment(segment)
    const next: string[] = []
    for (const path of current) {
      // A folder that is not there matches nothing; one that will not list is not "no match".
      const entries = await ctx.probe.list(path).catch(async error => {
        if (await stat(ctx, path)) throw error
        return []
      })
      for (const entry of entries) {
        const isHidden = entry.name.startsWith('.') && !segment.startsWith('.')
        if (!isHidden && wanted.test(entry.name)) next.push(join(path, entry.name))
      }
      if (next.length >= MAX_ARGS) break
    }
    current = next.slice(0, MAX_ARGS)
    if (current.length === 0) return []
  }
  return current
}

type Target = Path & { real: string; stat: FsStat }

async function existing(ctx: Ctx, paths: readonly Path[]): Promise<Target[]> {
  const stats = await Promise.all(paths.map(path => stat(ctx, path.abs)))
  return paths.flatMap((path, k) => {
    const found = stats[k]
    return found ? [{ ...path, real: found.realPath ?? path.abs, stat: found }] : []
  })
}

/** `/`, your home folder or one above it, or a top-level system folder. */
function isCatastrophic(path: string, home?: string): boolean {
  if (path === '/') return true
  if (home !== undefined && within(path, home)) return true
  return path.split('/').filter(Boolean).length === 1
}

/**
 * alwaysAllow: every target a plain literal path that exists, reached through
 * plain `cd`s, and both its spelling and its real path inside an allowed
 * folder. A real path another hook withheld is never allowed.
 */
function allowed(ctx: Ctx, f: Finding, paths: readonly Path[], found: readonly Target[]): boolean {
  if (ctx.allow.length === 0 || paths.length === 0 || found.length !== paths.length) return false
  if (!plainSteps(f.cd) || paths.some(p => !p.plain)) return false
  return found.every(t => t.stat.realPath !== undefined && isAllowed(t.abs, ctx.root, ctx.allow) && isAllowed(t.stat.realPath, ctx.rootReal, ctx.allow))
}

// ---------------------------------------------------------------- deletions

/** rm -r, and git clean once its dry run has named what it removes. */
async function remove(ctx: Ctx, f: Finding, where: string, notes: LastLookRow[], dir: string, paths: readonly Path[], from: 'words' | 'git-clean'): Promise<LastLookItem> {
  const found = await existing(ctx, paths)
  const name = (abs: string) => show(abs, ctx.cwd, ctx.home)
  if (found.length === 0) {
    const names = list(paths.map(p => name(p.abs)))
    if (from === 'words' && paths.every(p => p.plain) && plainSteps(f.cd)) {
      return item(f, where, { effect: 'nothing', summary: `Nothing found at these paths: ${names}`, tone: 'warning', rows: [...notes, { text: 'Held anyway: check these are the paths you mean.', tone: 'subtle' }] })
    }
    const why = from === 'git-clean' ? `its dry run named ${names}, which were not found where expected` : `nothing was found at ${names}, but the shell may read these paths differently`
    return unmeasured(f, where, why, notes)
  }
  const doomed = found.find(t => isCatastrophic(t.abs, ctx.home) || isCatastrophic(t.real, ctx.home))
  if (doomed) {
    return item(f, where, { summary: `It deletes ${name(doomed.abs)}: your home folder or a system folder. Too large to measure.`, tone: 'error', rows: notes, isCatastrophic: true })
  }
  if (from === 'words' && allowed(ctx, f, paths, found)) return allowedItem(f, where, notes)

  const [tree, view] = await Promise.all([measureTree(ctx, dir, found), gitView(ctx, dir, found.map(t => t.real), true)])
  const display = (real: string) => {
    const owner = found.find(t => within(t.real, real))
    return show(owner ? rebase(real, owner.real, owner.abs) : fromReal(ctx, real), ctx.cwd, ctx.home)
  }
  const rows = [...notes]
  const missing = paths.filter(p => !found.some(t => t.abs === p.abs))
  if (missing.length > 0) rows.push({ text: `Not found: ${list(missing.map(p => name(p.abs)))}`, tone: 'warning' })
  if (found.length > 1 && found.length <= 12) {
    for (const t of found) {
      const counted = tree.perTarget.get(t.real)
      const files = counted?.files ?? (t.stat.kind === 'dir' ? 0 : 1)
      const bytes = counted?.bytes ?? (t.stat.isLink ? 0 : t.stat.size)
      rows.push({ text: `${name(t.abs)}${t.stat.kind === 'dir' ? '/' : ''}  ${count(files, 'file')}, ${size(bytes)}`, tone: 'subtle' })
    }
  }
  const links = found.filter(t => t.stat.isLink && !t.slash)
  if (links.length > 0) rows.push({ text: `${list(links.map(t => name(t.abs)))}: a link, so only the link goes`, tone: 'subtle' })

  const lost = typeof view === 'object' ? [...view.changed].filter(([path, xy]) => !xy.includes('D') && found.some(t => within(t.real, path))) : []
  rows.push(...gitRows(view, lost, display, 'any of this'))
  if (typeof view === 'object' && view.tracked && view.tracked.size > 0) {
    rows.push({ text: `git can restore the last committed version of ${count(view.tracked.size, 'tracked file')}`, tone: 'subtle' })
  }
  const lostPaths = new Set(lost.map(([path]) => path))
  const sample = tree.sample.filter(path => !lostPaths.has(path))
  for (const path of sample.slice(0, MAX_ROWS)) rows.push({ text: display(path), tone: 'subtle' })
  const unlisted = Math.max(0, tree.files - lost.length - Math.min(sample.length, MAX_ROWS))
  rows.push(...tree.problems.map(text => ({ text, tone: 'warning' as const })))

  if (tree.isBlind) return unmeasured(f, where, tree.problems.join('; '), rows)
  const folders = found.filter(t => t.stat.kind === 'dir').length
  const summary = tree.files > 0 || folders === 0
    ? `Deletes ${tree.isLowerBound ? 'at least ' : ''}${count(tree.files, 'file')}, ${size(tree.bytes)}`
    : `Deletes ${count(folders, 'empty folder')}`
  return item(f, where, { summary, rows, moreRows: unlisted, files: tree.files, bytes: tree.bytes, unsaved: lost.length })
}

type Tree = {
  files: number
  bytes: number
  isLowerBound: boolean
  perTarget: Map<string, { files: number; bytes: number }>
  /** Real paths of some of the files, for the list. */
  sample: string[]
  problems: string[]
  /** Neither the list nor the size could be read. */
  isBlind: boolean
}

async function measureTree(ctx: Ctx, dir: string, targets: readonly Target[]): Promise<Tree> {
  const folders = targets.filter(t => t.stat.kind === 'dir' && (!t.stat.isLink || t.slash))
  const singles = targets.filter(t => !folders.includes(t))
  const tree: Tree = {
    files: singles.length,
    bytes: singles.reduce((sum, t) => sum + (t.stat.isLink ? 0 : t.stat.size), 0),
    isLowerBound: false,
    perTarget: new Map(),
    sample: singles.map(t => t.real),
    problems: [],
    isBlind: false,
  }
  if (folders.length === 0) return tree
  const reals = folders.map(t => t.real).slice(0, MAX_ARGS)
  const [listing, sizes] = await Promise.all([
    run(ctx, ['find', ...reals, '-type', 'f', '-print0'], dir, LIST_MS).catch(() => undefined),
    run(ctx, ['du', '-sk', ...reals], dir, LIST_MS).catch(() => undefined),
  ])
  if (listing) {
    const files = nulList(listing)
    tree.files += files.length
    tree.isLowerBound = listing.isStdoutTruncated || listing.exitCode !== 0
    tree.sample.push(...files.slice(0, MAX_ARGS))
    if (reals.length <= 20) {
      for (const real of reals) tree.perTarget.set(real, { files: files.filter(path => within(real, path)).length, bytes: 0 })
    }
    if (listing.exitCode !== 0) tree.problems.push('Some folders could not be read, so the count may be short.')
  } else tree.problems.push('Could not list the files.')
  if (sizes) {
    for (const [real, kib] of duLines(sizes.stdout)) {
      tree.bytes += kib * 1024
      const counted = tree.perTarget.get(real)
      if (counted) counted.bytes = kib * 1024
    }
  } else tree.problems.push('Could not add up the size.')
  tree.isBlind = !listing && !sizes
  return tree
}

async function findDelete(ctx: Ctx, f: Finding, where: string, notes: LastLookRow[], dir: string): Promise<LastLookItem> {
  const listing = f.findListing
  if (!listing) return unmeasured(f, where, 'its find expression could not be re-run safely', notes)
  // Never run a find that could write or execute, whatever built the listing.
  if (listing.some(t => FIND_WRITES.has(t))) return unmeasured(f, where, 'its find expression writes or runs commands', notes)
  const starts = f.targets.map(w => ({ abs: join(dir, w.text), slash: false, plain: isPlainPath(w) }))
  const names = list(starts.map(p => show(p.abs, ctx.cwd, ctx.home)))
  if (starts.some(p => isCatastrophic(p.abs, ctx.home))) {
    return unmeasured(f, where, `it searches ${names}, too much to measure`, notes)
  }
  const found = await existing(ctx, starts)
  if (found.length === 0) {
    if (starts.every(p => p.plain) && plainSteps(f.cd)) {
      return item(f, where, { effect: 'nothing', summary: `Nothing found at these paths: ${names}`, tone: 'warning', rows: [...notes, { text: 'Held anyway: check these are the paths you mean.', tone: 'subtle' }] })
    }
    return unmeasured(f, where, `nothing was found at ${names}, but the shell may read these paths differently`, notes)
  }
  // alwaysAllow never covers find: -L, -H or -follow (anywhere) reach through links.

  const dirReal = (await stat(ctx, dir))?.realPath ?? dir
  const out = await run(ctx, ['find', ...listing], dirReal, LIST_MS).catch(() => undefined)
  if (!out) return unmeasured(f, where, 'the find listing did not finish', notes)
  const matched = nulList(out).map(path => join(dirReal, path))
  // The shell's find (bfs, GNU) and the system find can disagree: an error or an
  // empty listing says nothing about what the real command deletes.
  if (out.exitCode !== 0) {
    return unmeasured(f, where, `the system find stopped with an error (${clip(firstLine(out.stderr), 100)}); the shell's find may read it differently`, notes)
  }
  if (matched.length === 0) return unmeasured(f, where, "the system find lists nothing for it, but the shell's find may match differently", notes)
  const display = (real: string) => show(fromReal(ctx, real), ctx.cwd, ctx.home)
  const topmost = matched.filter(path => !matched.some(other => other !== path && within(other, path)))
  const [sizes, view] = await Promise.all([
    run(ctx, ['du', '-sk', ...topmost.slice(0, MAX_ARGS)], dirReal, LIST_MS).catch(() => undefined),
    gitView(ctx, dirReal, found.map(s => s.real), false),
  ])
  const bytes = sizes ? duLines(sizes.stdout).reduce((sum, [, kib]) => sum + kib * 1024, 0) : 0
  const matchedSet = new Set(matched)
  const lost = typeof view === 'object' ? [...view.changed].filter(([path, xy]) => !xy.includes('D') && matchedSet.has(path)) : []
  const lostPaths = new Set(lost.map(([path]) => path))
  const rows = [...notes, ...gitRows(view, lost, display, 'these files')]
  const sample = matched.filter(path => !lostPaths.has(path)).slice(0, MAX_ROWS)
  for (const path of sample) rows.push({ text: display(path), tone: 'subtle' })
  if (!sizes) rows.push({ text: 'Could not add up the size.', tone: 'warning' })
  rows.push({ text: "Listed with the system find; the shell's find may match a little differently.", tone: 'subtle' })
  const lower = out.isStdoutTruncated ? 'at least ' : ''
  return item(f, where, {
    summary: `Deletes ${lower}${count(matched.length, 'path')}${sizes ? `, ${size(bytes)}` : ''}`,
    rows,
    moreRows: Math.max(0, matched.length - lost.length - sample.length),
    files: matched.length,
    bytes,
    unsaved: lost.length,
  })
}

async function clean(ctx: Ctx, f: Finding, where: string, notes: LastLookRow[], dir: string, git: { flags: string[]; forces: number; excludes: string[]; paths: Word[] }): Promise<LastLookItem> {
  const unknownPath = git.paths.find(w => !w.known)
  if (unknownPath) return unmeasured(f, where, `it names ${unknownPath.raw}, which is only known when it runs`, notes)
  // The same clean as a dry run: -n lists and never removes, even beside -f.
  // The forces are passed too: -ff also removes nested git repositories.
  const forces = Array.from({ length: Math.min(git.forces, 2) }, () => '-f')
  const args = ['clean', '-n', ...forces, ...git.flags.map(flag => `-${flag}`), ...git.excludes.flatMap(e => ['-e', e]), '--', ...git.paths.map(w => w.text)]
  const out = await gitRun(ctx, dir, args)
  if (out.exitCode !== 0) {
    const why = /not a git repository/i.test(out.stderr) ? 'it is not in a git repository' : `git clean -n failed: ${clip(firstLine(out.stderr), 120)}`
    return unmeasured(f, where, why, notes)
  }
  const lines = out.stdout.split('\n')
  const names = lines.flatMap(line => (line.startsWith('Would remove ') ? [unquote(line.slice('Would remove '.length))] : []))
  const skipped = lines.flatMap(line => (line.startsWith('Would skip repository ') ? [unquote(line.slice('Would skip repository '.length))] : []))
  const rows = [...notes, ...skipped.map(name => ({ text: `It skips the nested repository ${name}.`, tone: 'subtle' as const }))]
  if (names.length === 0) return unmeasured(f, where, 'its dry run (git clean -n) lists nothing to remove', rows)
  return remove(ctx, f, where, rows, dir, names.map(name => ({ abs: join(dir, name), slash: false, plain: false })), 'git-clean')
}

/** git's C-style quoting of an odd name: `"notes \"v2\".md"`. */
export function unquote(name: string): string {
  if (!(name.length >= 2 && name.startsWith('"') && name.endsWith('"'))) return name
  const escapes: Record<string, string> = { n: '\n', t: '\t', r: '\r', a: '\x07', b: '\b', f: '\f', v: '\v', '"': '"', '\\': '\\' }
  const bytes: number[] = []
  const body = name.slice(1, -1)
  for (let k = 0; k < body.length; k++) {
    const c = body[k] ?? ''
    if (c !== '\\') {
      for (const byte of new TextEncoder().encode(c)) bytes.push(byte)
      continue
    }
    const octal = /^[0-7]{3}/.exec(body.slice(k + 1))
    if (octal) {
      bytes.push(Number.parseInt(octal[0], 8))
      k += 3
    } else {
      const next = body[k + 1] ?? ''
      for (const byte of new TextEncoder().encode(escapes[next] ?? next)) bytes.push(byte)
      k += 1
    }
  }
  return new TextDecoder().decode(new Uint8Array(bytes))
}

async function overwrite(ctx: Ctx, f: Finding, where: string, notes: LastLookRow[], dir: string): Promise<LastLookItem> {
  const paths = await expand(ctx, dir, f.targets)
  if (typeof paths === 'string') return unmeasured(f, where, paths, notes)
  const path = paths[0]
  if (!path) return unmeasured(f, where, 'it names no file', notes)
  // The exception holds only for a command that is this redirect alone: in
  // `mv a tmp && echo x > tmp` the target exists by the time the redirect runs.
  const isPlain = path.plain && plainSteps(f.cd) && f.isSole === true
  // `stat` answers undefined only when the path positively does not exist; any
  // other failure throws, and the part is held unmeasured.
  const found = await stat(ctx, path.abs)
  const name = show(path.abs, ctx.cwd, ctx.home)
  // The one proof that lets a redirect through: a plain path that does not exist.
  if (!found) {
    return isPlain
      ? harmless(f, where, `Creates ${name}; nothing is overwritten`, notes)
      : unmeasured(f, where, `nothing was found at ${name}, but the shell may read the path differently`, notes)
  }
  // A folder, a link (even to nowhere), a device: no proof either way, so held.
  if (found.kind !== 'file' || found.isLink) {
    if (found.kind !== 'file') return unmeasured(f, where, `${name} is not a plain file`, notes)
    notes = [...notes, { text: `${name} is a link: the file it leads to is overwritten.`, tone: 'warning' }]
  }
  const real = found.realPath

  const view = await gitView(ctx, dir, [real ?? path.abs], true)
  const rows = [...notes]
  let unsaved = 0
  if (view === 'none') rows.push({ text: 'Not in a git repository: its old contents would be gone for good.', tone: 'warning' })
  else if (view === 'failed') rows.push({ text: 'git status failed, so unsaved work could not be checked.', tone: 'warning' })
  else {
    const xy = view.changed.get(real ?? path.abs)
    if (xy !== undefined && !xy.includes('D')) {
      unsaved = 1
      rows.push({ text: `It has unsaved work git cannot bring back (${describe(xy)}).`, tone: 'error' })
    } else if (view.tracked?.has(real ?? path.abs)) rows.push({ text: 'git can restore it as last committed.', tone: 'subtle' })
    else rows.push({ text: 'git ignores it: its old contents would be gone for good.', tone: 'warning' })
  }
  return item(f, where, { summary: `Overwrites ${name} (${size(found.size)})`, rows, files: 1, bytes: found.size, unsaved })
}

// ---------------------------------------------------------------- git

async function discard(ctx: Ctx, f: Finding, where: string, notes: LastLookRow[], dir: string): Promise<LastLookItem> {
  const git = f.git
  const top = await gitRun(ctx, dir, ['rev-parse', '--show-toplevel'])
  if (top.exitCode !== 0) return unmeasured(f, where, 'it is not in a git repository', notes)
  const root = top.stdout.trim()
  const display = (real: string) => show(fromReal(ctx, real), ctx.cwd, ctx.home)

  let specs: string[] = []
  let fromIndex = false
  let ref: string | undefined
  if (git?.sub === 'reset') {
    if (git.ref && !git.ref.known) return unmeasured(f, where, `it resets to ${git.ref.raw}, which is only known when it runs`, notes)
    ref = git.ref?.text
  } else if (git?.sub === 'discard') {
    const unknownPath = git.paths.find(w => !w.known)
    if (unknownPath) return unmeasured(f, where, `it names ${unknownPath.raw}, which is only known when it runs`, notes)
    if (git.mode === 'maybe-ref') {
      // `git checkout x` passes only as a proven branch switch (git refuses a
      // switch that would lose changes); every doubt is held as paths.
      const name = git.paths[0]?.text ?? ''
      if (await isBranchSwitch(ctx, dir, name)) return harmless(f, where, `Switches to branch ${name}; git refuses a switch that would lose changes`, notes)
    }
    if (git.mode !== 'all') specs = ['--', ...git.paths.map(w => w.text)]
    fromIndex = git.fromIndex && git.mode !== 'all'
  } else return unmeasured(f, where, 'unexpected git form', notes)

  if (ref !== undefined && ref !== 'HEAD') {
    const known = await gitRun(ctx, dir, ['rev-parse', '--verify', '--quiet', `${ref}^{commit}`])
    if (known.exitCode !== 0) return unmeasured(f, where, `git cannot find ${ref}`, notes)
  }
  const dropsCommits = ref !== undefined && ref !== 'HEAD'
  // diff-files and diff-index read the index without refreshing it: `git diff` would rewrite it.
  const numstatArgs = fromIndex ? ['diff-files', '--numstat', ...specs] : ['diff-index', '--numstat', 'HEAD', ...specs]
  const [status, numstat, branch, dropped, log] = await Promise.all([
    gitRun(ctx, dir, ['status', '--porcelain=v1', '-z', '--untracked-files=no', ...specs]),
    gitRun(ctx, dir, numstatArgs),
    gitRun(ctx, dir, ['rev-parse', '--abbrev-ref', 'HEAD']),
    dropsCommits ? gitRun(ctx, dir, ['rev-list', '--count', '--end-of-options', `${ref}..HEAD`]) : undefined,
    dropsCommits ? gitRun(ctx, dir, ['log', '--format=%h %s', '-n', '8', '--end-of-options', `${ref}..HEAD`]) : undefined,
  ])
  if (status.exitCode !== 0) return unmeasured(f, where, `git status failed: ${clip(firstLine(status.stderr), 120)}`, notes)
  if (dropped && dropped.exitCode !== 0) return unmeasured(f, where, `git could not count the commits it drops: ${clip(firstLine(dropped.stderr), 120)}`, notes)
  const changes = [...porcelain(status.stdout, root)].filter(([, xy]) => (fromIndex ? xy[1] !== ' ' : true))
  const lines = numstatLines(numstat.stdout, root)
  const commits = dropped ? Number.parseInt(dropped.stdout.trim(), 10) || 0 : 0
  if (changes.length === 0 && commits === 0) {
    return item(f, where, { effect: 'nothing', summary: 'Nothing to lose as far as git can tell: no uncommitted changes there', tone: 'warning', rows: notes })
  }
  const rows = [...notes]
  let added = 0
  let removed = 0
  if (changes.length > 0) {
    rows.push({ text: `${count(changes.length, 'file')} with uncommitted changes git cannot bring back:`, tone: 'error' })
    for (const [path, xy] of changes) {
      const stats = lines.get(path)
      added += stats?.added ?? 0
      removed += stats?.removed ?? 0
      rows.push({ text: `  ${display(path)}  ${stats ? `+${stats.added} -${stats.removed}` : describe(xy)}`, tone: 'error' })
    }
  }
  const onBranch = branch.exitCode === 0 ? branch.stdout.trim() : 'this branch'
  if (commits > 0) {
    rows.push({ text: `${count(commits, 'commit')} would leave ${onBranch}:`, tone: 'error' })
    for (const line of (log?.stdout ?? '').split('\n').filter(Boolean)) rows.push({ text: `  ${line}`, tone: 'subtle' })
    rows.push({ text: 'git reflog can still find dropped commits for a while.', tone: 'subtle' })
  }
  const parts = [
    ...(changes.length > 0 ? [`Discards uncommitted changes in ${count(changes.length, 'file')} (+${added} -${removed} lines)`] : []),
    ...(commits > 0 ? [`drops ${count(commits, 'commit')} from ${onBranch}`] : []),
  ]
  return item(f, where, { summary: capitalize(parts.join(' and ')), tone: 'error', rows, files: changes.length, unsaved: changes.length, commits })
}

/**
 * True only when git positively says `name` is a branch: a local branch, a
 * remote-tracking branch, or exactly one remote branch git would set up for
 * it; and no file or folder of that name makes the checkout ambiguous. A git
 * error answers false; a stat error throws (held).
 */
async function isBranchSwitch(ctx: Ctx, dir: string, name: string): Promise<boolean> {
  if (!/^[A-Za-z0-9._/-]+$/.test(name) || name.startsWith('-') || name.includes('..')) return false
  const local = await gitRun(ctx, dir, ['rev-parse', '--verify', '--quiet', `refs/heads/${name}`])
  let isBranch = local.exitCode === 0
  if (!isBranch) isBranch = (await gitRun(ctx, dir, ['rev-parse', '--verify', '--quiet', `refs/remotes/${name}`])).exitCode === 0
  if (!isBranch) {
    const guess = await gitRun(ctx, dir, ['for-each-ref', '--format=%(refname)', `refs/remotes/*/${name}`])
    isBranch = guess.exitCode === 0 && guess.stdout.split('\n').filter(Boolean).length === 1
  }
  if (!isBranch) return false
  return (await stat(ctx, join(dir, name))) === undefined
}

async function push(ctx: Ctx, f: Finding, where: string, notes: LastLookRow[], dir: string): Promise<LastLookItem> {
  const git = f.git
  if (git?.sub !== 'push') return unmeasured(f, where, 'unexpected git form', notes)
  if (git.isWholeRepo) return unmeasured(f, where, 'it force-pushes many branches at once', notes)
  if (git.remote && !git.remote.known) return unmeasured(f, where, `it pushes to ${git.remote.raw}, which is only known when it runs`, notes)
  const top = await gitRun(ctx, dir, ['rev-parse', '--show-toplevel'])
  if (top.exitCode !== 0) return unmeasured(f, where, 'it is not in a git repository', notes)

  type Pair = { local: string; name: string; isDelete: boolean }
  const pairs: Pair[] = []
  const branch = (await gitRun(ctx, dir, ['rev-parse', '--abbrev-ref', 'HEAD'])).stdout.trim()
  if (!git.remote) {
    let upstream = await gitRun(ctx, dir, ['rev-parse', '--abbrev-ref', '--symbolic-full-name', '@{push}'])
    if (upstream.exitCode !== 0) upstream = await gitRun(ctx, dir, ['rev-parse', '--abbrev-ref', '--symbolic-full-name', '@{upstream}'])
    if (upstream.exitCode !== 0) return unmeasured(f, where, 'no upstream branch is set, so what it would overwrite is unclear', notes)
    pairs.push({ local: 'HEAD', name: upstream.stdout.trim(), isDelete: false })
  } else if (git.refspecs.length === 0) {
    pairs.push({ local: 'HEAD', name: `${git.remote.text}/${branch}`, isDelete: false })
  } else {
    for (const spec of git.refspecs) {
      if (!spec.known) return unmeasured(f, where, `it pushes ${spec.raw}, which is only known when it runs`, notes)
      const [src = '', dst] = spec.text.replace(/^\+/, '').split(':')
      const target = (dst ?? src).replace(/^refs\/heads\//, '')
      pairs.push({ local: src || 'HEAD', name: `${git.remote.text}/${target === 'HEAD' ? branch : target}`, isDelete: src === '' })
    }
  }

  const fetchHead = (await gitRun(ctx, dir, ['rev-parse', '--git-path', 'FETCH_HEAD'])).stdout.trim()
  const fetched = fetchHead ? await stat(ctx, join(dir, fetchHead)) : undefined
  const age = fetched ? ago(ctx.now - fetched.mtimeMs) : 'never fetched here'
  const rows = [...notes]
  let total = 0
  let isBlind = false
  for (const pair of pairs.slice(0, 6)) {
    const remoteRef = `refs/remotes/${pair.name}`
    if (pair.isDelete) {
      rows.push({ text: `It deletes ${pair.name} on the remote.`, tone: 'error' })
      continue
    }
    const known = await gitRun(ctx, dir, ['rev-parse', '--verify', '--quiet', remoteRef])
    if (known.exitCode !== 0) {
      isBlind = true
      rows.push({ text: `No record of ${pair.name} here, so what it would overwrite is unknown.`, tone: 'warning' })
      continue
    }
    const range = `${pair.local}..${remoteRef}`
    const [counted, log] = await Promise.all([
      gitRun(ctx, dir, ['rev-list', '--count', '--end-of-options', range]),
      gitRun(ctx, dir, ['log', '--format=%h %an: %s', '-n', '8', '--end-of-options', range]),
    ])
    if (counted.exitCode !== 0) {
      isBlind = true
      rows.push({ text: `git could not compare with ${pair.name}.`, tone: 'warning' })
      continue
    }
    const n = Number.parseInt(counted.stdout.trim(), 10) || 0
    total += n
    if (n > 0) {
      rows.push({ text: `${count(n, 'commit')} on ${pair.name} would be overwritten:`, tone: 'error' })
      for (const line of log.stdout.split('\n').filter(Boolean)) rows.push({ text: `  ${line}`, tone: 'subtle' })
    }
  }
  rows.push({ text: `As of your last fetch (${age}); the remote may have moved since.`, tone: 'warning' })
  const names = list(pairs.map(p => p.name))
  const summary = total > 0 ? `Overwrites ${names}: ${count(total, 'commit')} there would be lost` : `Force-pushes ${names}; no commits would be lost as of your last fetch`
  return item(f, where, { effect: isBlind ? 'unknown' : 'some', summary, tone: total > 0 ? 'error' : 'warning', rows, commits: total })
}

async function branchDelete(ctx: Ctx, f: Finding, where: string, notes: LastLookRow[], dir: string): Promise<LastLookItem> {
  const git = f.git
  if (git?.sub !== 'branch') return unmeasured(f, where, 'unexpected git form', notes)
  const unknownName = git.names.find(w => !w.known)
  if (unknownName) return unmeasured(f, where, `it deletes ${unknownName.raw}, which is only known when it runs`, notes)
  const top = await gitRun(ctx, dir, ['rev-parse', '--show-toplevel'])
  if (top.exitCode !== 0) return unmeasured(f, where, 'it is not in a git repository', notes)
  const current = (await gitRun(ctx, dir, ['rev-parse', '--abbrev-ref', 'HEAD'])).stdout.trim()
  const rows = [...notes]
  const deleted: string[] = []
  let total = 0
  let isBlind = false
  for (const w of git.names.slice(0, 10)) {
    const name = w.text
    const exists = (await gitRun(ctx, dir, ['rev-parse', '--verify', '--quiet', `refs/heads/${name}`])).exitCode === 0
    if (!exists) {
      rows.push({ text: `No branch named ${name}.`, tone: 'subtle' })
      continue
    }
    if (name === current) rows.push({ text: `${name} is checked out, so git will refuse to delete it.`, tone: 'subtle' })
    deleted.push(name)
    // Commits on this branch and on no other branch, remote or tag.
    const only = [`refs/heads/${name}`, '--not', `--exclude=${name}`, '--branches', '--remotes', '--tags']
    const [counted, log] = await Promise.all([gitRun(ctx, dir, ['rev-list', '--count', ...only]), gitRun(ctx, dir, ['log', '--format=%h %s', '-n', '8', ...only])])
    if (counted.exitCode !== 0) {
      isBlind = true
      continue
    }
    const n = Number.parseInt(counted.stdout.trim(), 10) || 0
    total += n
    if (n > 0) {
      rows.push({ text: `${count(n, 'commit')} exist only on ${name}:`, tone: 'error' })
      for (const line of log.stdout.split('\n').filter(Boolean)) rows.push({ text: `  ${line}`, tone: 'subtle' })
    }
  }
  if (deleted.length === 0) return item(f, where, { effect: 'nothing', summary: 'No such branch found', tone: 'warning', rows })
  if (total > 0) rows.push({ text: 'git reflog can still find them for a while.', tone: 'subtle' })
  const summary = total > 0 ? `Deletes ${list(deleted)}: ${count(total, 'commit')} exist nowhere else` : `Deletes ${list(deleted)}; every commit is also on another branch`
  return item(f, where, { effect: isBlind ? 'unknown' : 'some', summary, tone: total > 0 ? 'error' : 'warning', rows, commits: total })
}

type GitView = { changed: Map<string, string>; tracked?: Set<string> } | 'none' | 'failed'

/** What git knows about these real paths: uncommitted entries, tracked files. */
async function gitView(ctx: Ctx, dir: string, reals: readonly string[], wantTracked: boolean): Promise<GitView> {
  const top = await gitRun(ctx, dir, ['rev-parse', '--show-toplevel']).catch(() => undefined)
  if (!top) return 'failed'
  if (top.exitCode !== 0) return 'none'
  const root = top.stdout.trim()
  const inside = reals.filter(real => within(root, real) && real !== join(root, '.git') && !within(join(root, '.git'), real))
  if (inside.length === 0) return 'none'
  const specs = inside.slice(0, MAX_ARGS).map(real => (real === root ? '.' : real.slice(root.length + 1)))
  // Literal pathspecs: a file named `a[1].txt` is that file, not a pattern.
  const status = await gitRun(ctx, root, ['--literal-pathspecs', 'status', '--porcelain=v1', '-z', '--untracked-files=all', '--', ...specs]).catch(() => undefined)
  if (!status || status.exitCode !== 0) return 'failed'
  const view: GitView = { changed: porcelain(status.stdout, root) }
  if (wantTracked) {
    const files = await gitRun(ctx, root, ['--literal-pathspecs', 'ls-files', '-z', '--', ...specs]).catch(() => undefined)
    if (files && files.exitCode === 0) view.tracked = new Set(nulList(files).map(path => join(root, path)))
  }
  return view
}

function gitRows(view: GitView, lost: [string, string][], display: (real: string) => string, what: string): LastLookRow[] {
  if (view === 'none') return [{ text: `Not in a git repository: git cannot bring back ${what}.`, tone: 'warning' }]
  if (view === 'failed') return [{ text: 'git status failed, so unsaved work could not be checked.', tone: 'warning' }]
  if (lost.length === 0) return []
  const rows: LastLookRow[] = [{ text: `${count(lost.length, 'file')} ${lost.length === 1 ? 'has' : 'have'} unsaved work you would lose:`, tone: 'error' }]
  for (const [path, xy] of lost.slice(0, 15)) rows.push({ text: `  ${display(path)}  (${describe(xy)})`, tone: 'error' })
  if (lost.length > 15) rows.push({ text: `  and ${count(lost.length - 15, 'more file')} with unsaved work`, tone: 'error' })
  return rows
}

// ---------------------------------------------------------------- headline

function headline(items: readonly LastLookItem[]): Pick<LastLookReport, 'headline' | 'headlineTone'> {
  const live = items.filter(i => !i.isAllowed && !i.isHarmless)
  const total = (key: 'unsaved' | 'commits' | 'files' | 'bytes') => live.reduce((sum, i) => sum + i[key], 0)
  const unsaved = total('unsaved')
  const commits = total('commits')
  if (live.some(i => i.isCatastrophic)) return { headline: 'It deletes your home folder or a system folder', headlineTone: 'error' }
  if (unsaved > 0) return { headline: `${count(unsaved, 'file')} ${unsaved === 1 ? 'has' : 'have'} unsaved work you would lose`, headlineTone: 'error' }
  if (commits > 0) return { headline: `${count(commits, 'commit')} would be lost`, headlineTone: 'error' }
  if (live.some(i => i.effect === 'unknown')) return { headline: 'Could not measure all of it: review it yourself', headlineTone: 'warning' }
  const files = total('files')
  if (files > 0) return { headline: `It would delete or overwrite ${count(files, 'file')} (${size(total('bytes'))})`, headlineTone: 'warning' }
  if (live.length > 0 && live.every(i => i.effect === 'nothing')) return { headline: 'Nothing found to destroy as far as it can tell: review it yourself', headlineTone: 'warning' }
  return { headline: 'Check what it would change before it runs', headlineTone: 'warning' }
}

/**
 * The pane's first line. "Can destroy work" only when the measurement found work to lose;
 * a command it could not fully check, or found nothing in, is held for review in neutral
 * words (the headline under it says which), so a harmless step never reads as a threat.
 */
export function holdTitle(items: readonly LastLookItem[]): string {
  const live = items.filter(i => !i.isAllowed && !i.isHarmless)
  const found = live.some(i => i.isCatastrophic || i.unsaved > 0 || i.commits > 0 || i.files > 0)
  return found ? 'Held: this command can destroy work' : 'Held for your review'
}

// ---------------------------------------------------------------- pieces

type Draft = {
  summary: string
  tone?: LastLookTone
  effect?: LastLookItem['effect']
  rows?: LastLookRow[]
  moreRows?: number
  files?: number
  bytes?: number
  unsaved?: number
  commits?: number
  isAllowed?: boolean
  isHarmless?: boolean
  isCatastrophic?: boolean
}

function blank(title: string): LastLookItem {
  return { title, effect: 'some', summary: '', summaryTone: 'normal', rows: [], moreRows: 0, files: 0, bytes: 0, unsaved: 0, commits: 0, isAllowed: false, isHarmless: false, isCatastrophic: false }
}

function item(f: Finding, where: string | undefined, d: Draft): LastLookItem {
  const rows = d.rows ?? []
  return {
    ...blank(clip(f.label, 400)),
    ...(where !== undefined && where !== '.' ? { where } : {}),
    effect: d.effect ?? 'some',
    summary: d.summary,
    summaryTone: d.tone ?? 'normal',
    rows: rows.slice(0, MAX_ROWS),
    moreRows: Math.max(0, rows.length - MAX_ROWS) + (d.moreRows ?? 0),
    files: d.files ?? 0,
    bytes: d.bytes ?? 0,
    unsaved: d.unsaved ?? 0,
    commits: d.commits ?? 0,
    isAllowed: d.isAllowed ?? false,
    isHarmless: d.isHarmless ?? false,
    isCatastrophic: d.isCatastrophic ?? false,
  }
}

function unmeasured(f: Finding, where: string | undefined, why: string, rows: LastLookRow[] = []): LastLookItem {
  return item(f, where, { effect: 'unknown', summary: COULD_NOT, tone: 'warning', rows: [{ text: capitalize(`${why}.`), tone: 'subtle' }, ...rows] })
}

function allowedItem(f: Finding, where: string, notes: LastLookRow[]): LastLookItem {
  return item(f, where, { summary: 'Inside your alwaysAllow folders', rows: notes, isAllowed: true })
}

/** Not destructive after all; see `isHarmless`. */
function harmless(f: Finding, where: string, summary: string, notes: LastLookRow[]): LastLookItem {
  return item(f, where, { effect: 'nothing', summary, rows: notes, isHarmless: true })
}

async function run(ctx: Ctx, argv: string[], cwd: string, timeoutMs: number): Promise<ProcessRunResult> {
  return ctx.probe.run(argv, cwd, timeoutMs)
}

async function gitRun(ctx: Ctx, dir: string, args: string[]): Promise<ProcessRunResult> {
  return run(ctx, [...GIT, ...args], dir, GIT_MS)
}

/** Undefined only when the path is not there; any other failure throws, so the part is held unmeasured. */
async function stat(ctx: Ctx, path: string): Promise<FsStat | undefined> {
  return ctx.probe.stat(path)
}

/** A real path as the person knows it: under their cwd's own spelling. */
function fromReal(ctx: Ctx, real: string): string {
  return rebase(real, ctx.cwdReal, ctx.cwd)
}

function nulList(out: ProcessRunResult): string[] {
  const parts = out.stdout.split('\0')
  // A cut stream ends mid-path: drop the partial one.
  if (out.isStdoutTruncated) parts.pop()
  return parts.filter(Boolean)
}

/** `du -sk` lines: [path, KiB]. */
export function duLines(stdout: string): [string, number][] {
  return stdout.split('\n').flatMap(line => {
    const m = /^(\d+)\t(.+)$/.exec(line)
    return m ? [[m[2] ?? '', Number(m[1])] as [string, number]] : []
  })
}

/** `git status --porcelain=v1 -z`: real path to its two-letter status. */
export function porcelain(stdout: string, root: string): Map<string, string> {
  const out = new Map<string, string>()
  const parts = stdout.split('\0')
  for (let k = 0; k < parts.length; k++) {
    const entry = parts[k] ?? ''
    if (entry.length < 4) continue
    const xy = entry.slice(0, 2)
    out.set(join(root, entry.slice(3)), xy)
    // A rename or copy is followed by the path it came from.
    if (xy[0] === 'R' || xy[0] === 'C') k++
  }
  return out
}

function numstatLines(stdout: string, root: string): Map<string, { added: number; removed: number }> {
  const out = new Map<string, { added: number; removed: number }>()
  for (const line of stdout.split('\n')) {
    const m = /^(\d+|-)\t(\d+|-)\t(.+)$/.exec(line)
    if (m) out.set(join(root, m[3] ?? ''), { added: Number(m[1]) || 0, removed: Number(m[2]) || 0 })
  }
  return out
}

function describe(xy: string): string {
  if (xy === '??') return 'never added to git'
  if (xy.includes('U')) return 'merge conflict'
  if (xy[0] === 'A') return 'new, staged'
  if (xy[0] === 'R') return 'renamed'
  if (xy[1] === 'M' || xy[1] === 'T') return 'modified'
  if (xy[0] === 'M') return 'staged changes'
  if (xy.includes('D')) return 'deleted'
  return 'changed'
}

export function count(n: number, noun: string): string {
  return `${grouped(n)} ${n === 1 ? noun : `${noun}s`}`
}

export function grouped(n: number): string {
  return String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ',')
}

export function size(bytes: number): string {
  const units = ['B', 'KB', 'MB', 'GB', 'TB']
  let value = bytes
  let unit = 0
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024
    unit++
  }
  return unit === 0 ? `${value} B` : `${value.toFixed(1)} ${units[unit]}`
}

function ago(ms: number): string {
  const minutes = Math.round(ms / 60_000)
  if (minutes < 2) return 'just now'
  if (minutes < 90) return `${minutes} min ago`
  const hours = Math.round(minutes / 60)
  if (hours < 36) return `${hours} h ago`
  return `${Math.round(hours / 24)} days ago`
}

function list(names: readonly string[]): string {
  if (names.length <= 3) return names.join(', ')
  return `${names.slice(0, 3).join(', ')} and ${names.length - 3} more`
}

function firstLine(text: string): string {
  return text.trim().split('\n')[0] ?? ''
}

function clip(text: string, max: number): string {
  return text.length <= max ? text : `${text.slice(0, max - 3)}...`
}

function capitalize(text: string): string {
  return text.charAt(0).toUpperCase() + text.slice(1)
}

function short(error: unknown): string {
  const message = error instanceof Error ? error.message : String(error)
  return clip(message, 120)
}

